using Archy.Features.Decisions.ArchitectureDecisions; using Archy.SharedKernel.Primitives;
namespace Archy.Features.Placement.ApplyPlacementDecisionFeedback;
/// <summary>Feedback is tied to one placement finding identity, never a global module or threshold.</summary>
public sealed class PlacementDecisionFeedbackPolicy : IPlacementDecisionFeedbackPolicy { public PlacementDecisionFeedback Evaluate(string placementFindingId,IReadOnlyList<ArchitectureDecision> decisions){ArgumentException.ThrowIfNullOrWhiteSpace(placementFindingId);ArgumentNullException.ThrowIfNull(decisions);var relevant=decisions.Where(d=>d is not null&&d.DecisionType==PlacementReviewDecisionFactory.DecisionType&&d.Targets.Any(t=>t.Kind==ArchitectureTargetKind.PlacementFinding&&t.StableId==placementFindingId)).OrderByDescending(d=>d.OccurredAtUtc).ThenByDescending(d=>d.DecisionId,StringComparer.Ordinal).ToArray();return new(relevant.FirstOrDefault()?.Resolution==DecisionResolution.Ignored,relevant.FirstOrDefault()?.Resolution,[..relevant.Select(d=>d.DecisionId)]);}}
